function range(from, to) {
    return new Proxy({}, {
        has(target, key) {
            if (typeof key !== "string") return false;
            const n = Number(key);       // 10 in r -> key = "10"
            return Number.isInteger(n) && n >= from && n <= to;
        },
    });
}

