function withNegativeIndex(array) {
    const normalize = (target, key) =>
        typeof key === "string" && /^-\d+$/.test(key) ? String(target.length + Number(key)) : key;

    return new Proxy(array, {
        get: (target, key, receiver) => Reflect.get(target, normalize(target, key), receiver),
        set: (target, key, value, receiver) => Reflect.set(target, normalize(target, key), value, receiver),
    });
}

