function strictEnum(...names) {
    const values = Object.freeze(Object.fromEntries(names.map((n) => [n, n])));
    return new Proxy(values, {
        get(target, key) {
            if (typeof key === "string" && !Object.hasOwn(target, key)) {
                throw new ReferenceError(`Status.${key} mavjud emas`);
            }
            return target[key];
        },
    });
}

