function createHeaders(init = {}) {
    const lower = (key) => (typeof key === "string" ? key.toLowerCase() : key);
    const headers = new Proxy({}, {
        get: (t, key, r) => Reflect.get(t, lower(key), r),
        set: (t, key, value, r) => Reflect.set(t, lower(key), String(value), r),
        has: (t, key) => Reflect.has(t, lower(key)),
        deleteProperty: (t, key) => Reflect.deleteProperty(t, lower(key)),
    });
    Object.assign(headers, init);      // set trap orqali
    return headers;
}

