const targetMap = new WeakMap();
let activeEffect = null;

function track(target, key) {
    if (!activeEffect) return;
    let deps = targetMap.get(target);
    if (!deps) targetMap.set(target, (deps = new Map()));
    let effects = deps.get(key);
    if (!effects) deps.set(key, (effects = new Set()));
    effects.add(activeEffect);
}

function trigger(target, key) {
    const effects = targetMap.get(target)?.get(key);
    if (effects) for (const fn of [...effects]) fn();
}

function reactive(obj) {
    return new Proxy(obj, {
        get(target, key, receiver) {
            track(target, key);
            return Reflect.get(target, key, receiver);
        },
        set(target, key, value, receiver) {
            const old = target[key];
            const ok = Reflect.set(target, key, value, receiver);
            if (!Object.is(old, value)) trigger(target, key);
            return ok;
        },
    });
}

function effect(fn) {
    const run = () => {
        activeEffect = run;
        try {
            fn();
        } finally {
            activeEffect = null;
        }
    };
    run();
}

const cart = reactive({ price: 5000, qty: 2, note: "" });
