    const state = new Proxy(initial, {
        set(target, key, value, receiver) {
            const ok = Reflect.set(target, key, value, receiver);
            render(key, value);
            return ok;
        },
    });
    for (const [key, value] of Object.entries(initial)) render(key, value);
    return state;
}

