const METHODS = new Set(["get", "post", "put", "delete"]);

function createApi(baseUrl, transport) {
    const node = (parts) =>
        new Proxy(() => {}, {
            get(target, key) {
                if (typeof key !== "string" || key === "then") return undefined;
                return node([...parts, key]);
            },
            apply(target, thisArg, args) {
                const last = parts.at(-1);
                if (METHODS.has(last)) {
                    const url = `${baseUrl}/${parts.slice(0, -1).join("/")}`;
                    return transport(last.toUpperCase(), url, args[0]);
                }
                return node([...parts, ...args.map(String)]);   // api.users(7) -> /users/7
            },
        });
    return node([]);
}

