function observable(initial) {
    let value = initial;
    const listeners = new Set();
    return {
        get: () => value,
        set(next) {
            if (Object.is(next, value)) return; // o'zgarmasa xabar yo'q
            const prev = value;
            value = next;
            listeners.forEach((fn) => fn(next, prev));
        },
        subscribe(fn, { immediate = false } = {}) {
            listeners.add(fn);
            if (immediate) fn(value, undefined);
            return () => listeners.delete(fn);
        },
    };
}

