            this.#members.get(to)?.receive(from, `(shaxsiy) ${text}`);
        } else {
            this.#broadcast(from, text);
        }
    }
    #broadcast(from, text) {
        for (const [name, user] of this.#members) {
            if (name !== from) user.receive(from, text);
        }
    }
}

