const rules = {
    required: (v) => (v !== "" && v != null) || "majburiy maydon",
    email: (v) => /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(v) || "email noto'g'ri",
    min: (n) => (v) => String(v).length >= n || `kamida ${n} belgi`,
    match: (other, label) => (v, form) => v === form[other] || `${label} bilan mos emas`,
};

const schema = {
    email: [rules.required, rules.email],
    password: [rules.required, rules.min(8)],
    confirm: [rules.match("password", "parol")],
};

function validate(form, schema) {
    const errors = {};
    for (const [field, checks] of Object.entries(schema)) {
        for (const check of checks) {
            const result = check(form[field], form);
            if (result !== true) {
                errors[field] = result;
                break; // birinchi xato yetadi
            }
        }
    }
    return errors;
}

