function macro(name, commands) {
    return {
        name,
        execute() {
            const done = [];
            try {
                for (const cmd of commands) {
                    cmd.execute();
                    done.push(cmd);
                }
            } catch (e) {
                for (const cmd of done.reverse()) cmd.undo(); // orqaga qaytarish
                throw e;
            }
        },
    };
}

