class LinkedList {
    #head = null;
    #tail = null;

    push(value) {
        const node = { value, next: null };
        if (this.#tail) this.#tail.next = node;
        else this.#head = node;
        this.#tail = node;
        return this;
    }

    // Iterator qolipi: node/next haqida hech kim bilmaydi
    *[Symbol.iterator]() {
        for (let cur = this.#head; cur; cur = cur.next) yield cur.value;
    }
}

