const orderMachine = {
    initial: "pending",
    transitions: {
        pending: { pay: "paid", cancel: "cancelled" },
        paid: { ship: "shipped", refund: "refunded" },
        shipped: { deliver: "delivered" },
        delivered: {},
        cancelled: {},
        refunded: {},
    },
};

function createMachine({ initial, transitions }) {
    let state = initial;
    return {
        get state() {
            return state;
        },
        can(event) {
            return Object.hasOwn(transitions[state], event);
        },
        send(event) {
            if (!this.can(event)) {
                console.log(`  x "${state}" holatida "${event}" mumkin emas`);
                return false;
            }
            const next = transitions[state][event];
            console.log(`  ${state} --${event}--> ${next}`);
            state = next;
            return true;
        },
    };
}

const order = createMachine(orderMachine);
