function createMachine(config, context) {
    let state = config.initial;
    const listeners = [];
    return {
        get state() {
            return state;
        },
        onTransition(fn) {
            listeners.push(fn);
        },
        send(event) {
            const t = config.states[state].on?.[event];
            if (!t) return false;
            const { target, guard } = typeof t === "string" ? { target: t } : t;
            if (guard && !guard(context)) {
                console.log(`guard: ${event} rad etildi`);
                return false;
            }
            const prev = state;
            state = target;
            config.states[state].entry?.(context);
            listeners.forEach((fn) => fn(prev, state, event));
            return true;
        },
    };
}

