function createApp() {
    const stack = [];
    return {
        use(fn) {
            stack.push(fn);
            return this;
        },
        handle(req) {
            const res = { status: 200, body: null };
            let i = 0;
            function next(err) {
                const fn = stack[i++];
                if (!fn) return;
                const isErrorHandler = fn.length === 4;
                if (err) return isErrorHandler ? fn(err, req, res, next) : next(err);
                if (isErrorHandler) return next();
                try {
                    fn(req, res, next);
                } catch (e) {
                    next(e);
                }
            }
            next();
            return res;
        },
    };
}

const app = createApp()
    .use((req, res, next) => {
        console.log(`${req.method} ${req.url}`);
        next();
    })
