function compose(middlewares) {
    return function (ctx) {
        let last = -1;
        function dispatch(i) {
            if (i <= last) return Promise.reject(new Error("next() ikki marta chaqirildi"));
            last = i;
            const fn = middlewares[i];
            if (!fn) return Promise.resolve();
            try {
                return Promise.resolve(fn(ctx, () => dispatch(i + 1)));
            } catch (e) {
                return Promise.reject(e);
            }
        }
        return dispatch(0);
    };
}

