class Container {
    #factories = new Map();
    #singletons = new Map();

    register(name, factory, { singleton = true } = {}) {
        this.#factories.set(name, { factory, singleton });
        return this;
    }
    resolve(name, chain = []) {
        if (chain.includes(name)) {
            throw new Error(`Aylanma bog'liqlik: ${[...chain, name].join(" -> ")}`);
        }
        const entry = this.#factories.get(name);
        if (!entry) throw new Error(`Ro'yxatda yo'q: ${name}`);
        if (entry.singleton && this.#singletons.has(name)) return this.#singletons.get(name);
        const get = (dep) => this.resolve(dep, [...chain, name]);
        const instance = entry.factory(get);
        if (entry.singleton) this.#singletons.set(name, instance);
        return instance;
    }
}

