function createStore(handlers, initialState, middlewares = []) {
    let state = initialState;
    const listeners = new Set();
    const past = [];
    const reducer = (s, a) => (Object.hasOwn(handlers, a.type) ? handlers[a.type](s, a) : s);

    const store = {
        getState: () => state,
        subscribe(fn) {
            listeners.add(fn);
            return () => listeners.delete(fn);
        },
        dispatch(action) {
            past.push(state);
            state = reducer(state, action);
            listeners.forEach((fn) => fn(state, action));
            return action;
        },
        undo() {
            if (!past.length) return;
            state = past.pop();
            listeners.forEach((fn) => fn(state, { type: "@@undo" }));
        },
    };
    // Birinchi middleware eng tashqi qatlam bo'ladi
    let dispatch = store.dispatch;
    for (const mw of middlewares.toReversed()) dispatch = mw(store)(dispatch);
    store.dispatch = dispatch;
    return store;
}

