function debounce(fn, wait) {
    let timer = null;
    return function (...args) {
        clearTimeout(timer);                       // oldingi rejani bekor qilamiz
        timer = setTimeout(() => {
            timer = null;
            fn.apply(this, args);                  // oxirgi chaqiruvning this va argumentlari
        }, wait);
    };
}

const onInput = debounce((text) => console.log("Qidiruv:", text), 300);

function debounce(fn, wait, { leading = false, trailing = true } = {}) {
    let timer = null;
    let lastArgs = null;
    let lastThis = null;

    function invoke() {
        const args = lastArgs;
        const self = lastThis;
        lastArgs = lastThis = null;                // bir chaqiruv ikki marta bajarilmasin
        return fn.apply(self, args);
    }
    function debounced(...args) {
        const isFirst = timer === null;
        lastArgs = args;
        lastThis = this;
        clearTimeout(timer);
        timer = setTimeout(() => {
            timer = null;
            if (trailing && lastArgs) invoke();
        }, wait);
        if (isFirst && leading) return invoke();
    }
    debounced.cancel = () => {
        clearTimeout(timer);
        timer = lastArgs = lastThis = null;
    };
    debounced.flush = () => {
        if (timer === null) return undefined;
        clearTimeout(timer);
        timer = null;
        return lastArgs ? invoke() : undefined;
    };
    debounced.pending = () => timer !== null;
    return debounced;
}

function throttle(fn, interval) {
    let timer = null;
    let pendingArgs = null;

    function windowEnd() {
        if (pendingArgs) {
            fn(...pendingArgs);                    // trailing: oyna davomidagi oxirgi chaqiruv
            pendingArgs = null;
            timer = setTimeout(windowEnd, interval);
        } else {
            timer = null;                          // oyna bo'sh o'tdi — throttle "dam oladi"
        }
    }
    return (...args) => {
        if (timer === null) {
            fn(...args);                           // leading: darhol
            timer = setTimeout(windowEnd, interval);
        } else {
            pendingArgs = args;                    // oyna ichida — faqat eslab qolamiz
        }
    };
}

// bir xil hodisalar oqimi, wait = interval = 50 ms
// hodisalar:    a@0  b@10  c@20  d@30  e@40       f@120  g@130       h@250
// throttle 50:  a@0                    e@50       f@120  g@170       h@250
// debounce 50:                               e@90        g@180       h@300

function memoize(fn, keyOf = (...args) => JSON.stringify(args)) {
    const cache = new Map();
    function memoized(...args) {
        const key = keyOf(...args);
        if (cache.has(key)) return cache.get(key);   // has: undefined natija ham keshlanadi
        const value = fn.apply(this, args);
        cache.set(key, value);
        return value;
    }
    memoized.cache = cache;                          // tashqaridan tozalash uchun
    return memoized;
}

function memoizeAsync(fn) {
    const cache = new Map();
    return (key) => {
        if (cache.has(key)) return cache.get(key);
        const promise = fn(key).catch((error) => {
            cache.delete(key);                     // xato keshda qolmasin — keyingi safar qayta urinamiz
            throw error;
        });
        cache.set(key, promise);                   // natijani emas, Promise'ni await'dan OLDIN saqlaymiz
        return promise;
    };
}

