function memoizeLRU(fn, max) {
    const cache = new Map();
    const stats = { hits: 0, misses: 0, evictions: 0 };
    function memoized(arg) {
        if (cache.has(arg)) {
            stats.hits++;
            const value = cache.get(arg);
            cache.delete(arg);
            cache.set(arg, value);
            return value;
        }
        stats.misses++;
        const value = fn(arg);
        cache.set(arg, value);
        if (cache.size > max) {
            cache.delete(cache.keys().next().value);
            stats.evictions++;
        }
        return value;
    }
    memoized.stats = stats;
    memoized.cache = cache;
    return memoized;
}

