function memoizeTTL(fn, ttl, now = Date.now) {
    const cache = new Map();
    return (key) => {
        const hit = cache.get(key);
        if (hit && now() < hit.expires) return hit.value;
        const value = fn(key);
        cache.set(key, { value, expires: now() + ttl });
        return value;
    };
}

