function memoizeOne(fn) {
    let lastArgs = null;
    let lastResult;
    return (...args) => {
        const same =
            lastArgs !== null &&
            args.length === lastArgs.length &&
            args.every((arg, i) => Object.is(arg, lastArgs[i]));
        if (!same) {
            lastResult = fn(...args);
            lastArgs = args;
        }
        return lastResult;
    };
}

