function debounce(fn, wait) {
    let timer = null;
    function run() {
        clearTimeout(timer);
        timer = null;
        fn();
    }
    function debounced() {
        clearTimeout(timer);
        timer = setTimeout(run, wait);
    }
    debounced.pending = () => timer !== null;
    debounced.flush = () => timer !== null && run();
    return debounced;
}

