function rateLimit(fn, { limit, interval }) {
    const queue = [];
    let timer = null;
    let windowNo = 0;

    function drain() {
        if (queue.length === 0) {
            timer = null;                          // navbat bo'sh — to'xtaymiz
            return;
        }
        windowNo++;
        for (const { args, resolve, reject } of queue.splice(0, limit)) {
            Promise.resolve()
                .then(() => fn(windowNo, ...args))   // o'quv uchun oyna raqamini ham beramiz
                .then(resolve, reject);
        }
        timer = setTimeout(drain, interval);       // keyingi oyna
    }
    return (...args) =>
        new Promise((resolve, reject) => {
            queue.push({ args, resolve, reject });
            if (timer === null) timer = setTimeout(drain, 0);
        });
}

