const roots = ["global"];

function mark(heap, roots) {
    const marked = new Set();
    const stack = [...roots];
    while (stack.length > 0) {
        const name = stack.pop();
        if (marked.has(name)) continue;
        marked.add(name);
        stack.push(...heap[name]);
    }
    return marked;
}

function sweep(heap, marked) {
    const freed = [];
    for (const name of Object.keys(heap)) {
        if (!marked.has(name)) {
            freed.push(name);
            delete heap[name];
        }
    }
    return freed;
}

