class RcObject {
    constructor(name) {
        this.name = name;
        this.count = 0;
        this.refs = [];
    }
}

function addRef(from, to) {
    from.refs.push(to);
    to.count++;
}

function release(obj, freed) {
    obj.count--;
    if (obj.count === 0) {
        freed.push(obj.name);
        for (const child of obj.refs) release(child, freed);
    }
}

