const young = [];
const old = [];
const stats = { dead: 0, promoted: 0 };

function allocate(name, lifetime) {
    young.push({ name, lifetime, survived: 0 });
}

function scavenge() {
    const survivors = [];
    for (const obj of young) {
        obj.lifetime--;
        if (obj.lifetime <= 0) {
            stats.dead++;               // o'lgan: nusxalanmaydi
            continue;
        }
        obj.survived++;
        if (obj.survived >= 2) {
            old.push(obj.name);         // ikki marta omon qoldi -> old
            stats.promoted++;
        } else {
            survivors.push(obj);        // ikkinchi semi-space ga ko'chirildi
        }
    }
    young.length = 0;
    young.push(...survivors);
}

