function createCache(limit = Infinity) {
    const map = new Map();
    return {
        get(key, compute) {
            if (map.has(key)) {
                const value = map.get(key);
                map.delete(key);       // LRU: yozuvni oxiriga ko'chirish
                map.set(key, value);
                return value;
            }
            const value = compute(key);
            map.set(key, value);
            if (map.size > limit) map.delete(map.keys().next().value);   // eng eskisi
            return value;
        },
        get size() {
            return map.size;
        },
    };
}

