const pending = new Map();
let nextId = 1;

function requestLeaky(send) {
    const id = nextId++;
    return new Promise((resolve) => {
        pending.set(id, resolve);
        send(id);   // javob kelmasa, resolve Map'da abadiy qoladi
    });
}

function requestFixed(send, ms) {
    const id = nextId++;
    const { promise, resolve, reject } = Promise.withResolvers();
    pending.set(id, resolve);
    const timer = setTimeout(() => reject(new Error(`#${id} timeout`)), ms);
    send(id);
    return promise.finally(() => {
        clearTimeout(timer);
        pending.delete(id);   // har qanday natijada tozalanadi
    });
}

