class RingBuffer {
    #items;
    #start = 0;
    #size = 0;

    constructor(capacity) {
        this.#items = new Array(capacity);
    }

    push(item) {
        const capacity = this.#items.length;
        this.#items[(this.#start + this.#size) % capacity] = item;   // eski yozuv ustidan
        if (this.#size < capacity) this.#size++;
        else this.#start = (this.#start + 1) % capacity;
    }

    toArray() {
        const capacity = this.#items.length;
        return Array.from({ length: this.#size }, (_, i) => this.#items[(this.#start + i) % capacity]);
    }
}

