class Vector {
    constructor() {
        this.x = 0;
        this.y = 0;
    }
}

class Pool {
    #free = [];
    created = 0;
    reused = 0;

    acquire() {
        if (this.#free.length > 0) {
            this.reused++;
            return this.#free.pop();
        }
        this.created++;
        return new Vector();
    }

    release(obj) {
        obj.x = 0;
        obj.y = 0;   // eski holat qolmasin
        this.#free.push(obj);
    }
}

