function setIn(obj, [key, ...rest], value) {
    const nextValue = rest.length === 0 ? value : setIn(obj?.[key] ?? {}, rest, value);
    if (Array.isArray(obj)) return obj.with(key, nextValue);
    return { ...obj, [key]: nextValue };
}

const state = {
