function updateIn(obj, path, fn) {
    if (path.length === 0) return fn(obj);
    const [key, ...rest] = path;
    const child = updateIn(obj[key], rest, fn);
    return Array.isArray(obj) ? obj.with(key, child) : { ...obj, [key]: child };
}

