// Qoida: (qiymat) => xato matni yoki null
const rules = {
    name: [(v) => (v.trim().length < 2 ? "ism kamida 2 harf" : null)],
    email: [(v) => (!v.includes("@") ? "email noto'g'ri" : null)],
    age: [
        (v) => (!Number.isInteger(v) ? "yosh butun son bo'lsin" : null),
        (v) => (v < 16 ? "16 yoshdan katta bo'lsin" : null),
    ],
};

function validate(form) {
    const errors = Object.entries(rules).flatMap(([field, checks]) =>
        checks
            .map((check) => check(form[field]))
            .filter(Boolean)
            .map((msg) => `${field}: ${msg}`),
    );
    return errors.length === 0 ? Ok(form) : Err(errors);
}

console.log(validate({ name: "Nodir", email: "nodir@mail.uz", age: 20 }));
