const mapping = (fn) => (reducer) => (acc, x) => reducer(acc, fn(x));
const filtering = (pred) => (reducer) => (acc, x) => (pred(x) ? reducer(acc, x) : acc);
const compose = (...fns) => (x) => fns.reduceRight((acc, fn) => fn(acc), x);

const toArray = (acc, x) => {
    acc.push(x);
    return acc;
};
const sum = (acc, x) => acc + x;
const max = (acc, x) => Math.max(acc, x);

const isOdd = (n) => n % 2 === 1;
const square = (n) => n * n;

// Ma'lumot oqimi: avval filter, keyin map
const xform = compose(filtering(isOdd), mapping(square));

const nums = [1, 2, 3, 4, 5, 6, 7];
