const trace = (steps, label, fn) => (n) => {
    steps.push(`${label}(${n})`);
    return fn(n);
};
const nums = [1, 2, 3, 4, 5, 6];

const eagerSteps = [];
const eager = nums
    .map(trace(eagerSteps, "map", (n) => n * 10))
    .filter(trace(eagerSteps, "filter", (n) => n > 20))
    .slice(0, 2);

const lazySteps = [];
const lazy = nums
    .values()
    .map(trace(lazySteps, "map", (n) => n * 10))
    .filter(trace(lazySteps, "filter", (n) => n > 20))
    .take(2)
    .toArray();

