import { useState } from "react";

export function TodoList() {
    const [todos, setTodos] = useState([{ id: 1, text: "Kitob o'qish", done: false }]);

    function toggleWrong(id) {
        const todo = todos.find((t) => t.id === id);
        todo.done = !todo.done;   // ✖ mutatsiya
        setTodos(todos);          // ✖ o'sha havola — React o'zgarishni sezmaydi
    }

    function toggle(id) {
        setTodos((prev) => prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
    }

    function add(text) {
        setTodos((prev) => [...prev, { id: prev.length + 1, text, done: false }]);
    }

    return (
        <div>
            <ul>
                {todos.map((t) => (
                    <li key={t.id} onClick={() => toggle(t.id)} onDoubleClick={() => toggleWrong(t.id)}>
                        {t.done ? "✔" : "○"} {t.text}
                    </li>
                ))}
            </ul>
            <button onClick={() => add("Yangi vazifa")}>Qo'shish</button>
        </div>
    );
}

const initialState = { todos: [], filter: "all", nextId: 1 };

function reducer(state = initialState, action) {
    switch (action.type) {
        case "todo/added":
            return {
                ...state,
                todos: [...state.todos, { id: state.nextId, text: action.text, done: false }],
                nextId: state.nextId + 1,
            };
        case "todo/toggled":
            return {
                ...state,
                todos: state.todos.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t)),
            };
        case "filter/changed":
            return { ...state, filter: action.filter };
        default:
            return state;
    }
}

const actions = [
    { type: "todo/added", text: "Reja tuzish" },
    { type: "todo/added", text: "Kod yozish" },
    { type: "todo/toggled", id: 1 },
    { type: "unknown" },
    { type: "filter/changed", filter: "done" },
];

let state = reducer(undefined, { type: "init" });
for (const action of actions) {
    const next = reducer(state, action);
    console.log(`${action.type.padEnd(15)} yangi holat: ${next !== state}, todos umumiy: ${next.todos === state.todos}`);
    state = next;
}
console.log(state.todos.map((t) => `${t.id}. ${t.text} ${t.done ? "✔" : "○"}`));

// Time travel: action'larni qayta o'ynatish aynan shu holatni beradi
const replayed = actions.reduce(reducer, undefined);
console.log(JSON.stringify(replayed) === JSON.stringify(state));

function createSelector(inputSelectors, compute) {
    let lastInputs = null;
    let lastResult;
    let computations = 0;
    const selector = (state) => {
        const inputs = inputSelectors.map((select) => select(state));
        const same = lastInputs !== null && inputs.every((value, i) => value === lastInputs[i]);
        if (!same) {
            lastResult = compute(...inputs);
            lastInputs = inputs;
            computations++;
        }
        return lastResult;
    };
    selector.computations = () => computations;
    return selector;
}

const selectVisible = createSelector(
    [(s) => s.todos, (s) => s.filter],
    (todos, filter) => (filter === "done" ? todos.filter((t) => t.done) : todos),
);

let state = { todos: [{ id: 1, done: true }, { id: 2, done: false }], filter: "done", user: "Ali" };
const r1 = selectVisible(state);

state = { ...state, user: "Vali" };                                     // todos o'sha havola
const r2 = selectVisible(state);

state = { ...state, todos: [...state.todos, { id: 3, done: true }] };   // yangi todos
const r3 = selectVisible(state);

console.log(r1 === r2, r1.length, r3.length);
console.log("hisoblashlar soni:", selectVisible.computations());

state.todos.push({ id: 4, done: true });   // ✖ mutatsiya — selektor sezmaydi
console.log(selectVisible(state).length, "— eskirgan natija");

const createHistory = (present) => ({ past: [], present, future: [] });

const commit = (h, next) => ({ past: [...h.past, h.present], present: next, future: [] });

const undo = (h) =>
    h.past.length === 0
        ? h
        : { past: h.past.slice(0, -1), present: h.past.at(-1), future: [h.present, ...h.future] };

const redo = (h) =>
    h.future.length === 0
        ? h
        : { past: [...h.past, h.present], present: h.future[0], future: h.future.slice(1) };

const doc = { title: "Hisobot", blocks: [{ id: 1, text: "Kirish" }], meta: { author: "Laylo" } };

let h = createHistory(doc);
h = commit(h, { ...h.present, title: "Yillik hisobot" });
h = commit(h, { ...h.present, blocks: [...h.present.blocks, { id: 2, text: "Xulosa" }] });
console.log(h.present.title, h.present.blocks.length);

h = undo(h);
console.log(h.present.title, h.present.blocks.length);
h = undo(h);
console.log(h.present.title, h.past.length, h.future.length);
h = undo(h);                                   // tarix bo'sh — o'sha holat qaytadi
h = redo(h);
console.log(h.present.title);

// Barcha versiyalar bitta meta obyektini bo'lishadi
console.log(h.present.meta === doc.meta, h.future[0].meta === doc.meta);

const pipe = (...fns) => (x) => fns.reduce((acc, fn) => fn(acc), x);
const Ok = (value) => ({ ok: true, value, map: (fn) => Ok(fn(value)) });
const Err = (error) => ({ ok: false, error, map: () => Err(error) });

const validate = (cart) => {
    if (cart.items.length === 0) return Err("Savatcha bo'sh");
    const bad = cart.items.find((i) => i.qty <= 0);
    return bad ? Err(`${bad.name}: miqdor noto'g'ri`) : Ok(cart);
};

const withSubtotal = (cart) => ({ ...cart, subtotal: cart.items.reduce((s, i) => s + i.price * i.qty, 0) });
const withDiscount = (rules) => (cart) => ({ ...cart, discount: rules[cart.promo]?.(cart.subtotal) ?? 0 });
const withTax = (percent) => (cart) => ({ ...cart, tax: Math.round(((cart.subtotal - cart.discount) * percent) / 100) });
const withTotal = (cart) => ({ ...cart, total: cart.subtotal - cart.discount + cart.tax });

const promoRules = {
    YANGI10: (sum) => Math.round(sum / 10),
    MINUS20K: (sum) => (sum >= 100000 ? 20000 : 0),
};

const calculate = pipe(withSubtotal, withDiscount(promoRules), withTax(12), withTotal);
const checkout = (cart) => validate(cart).map(calculate);

const carts = [
    { promo: "YANGI10", items: [{ name: "Kitob", price: 45000, qty: 2 }, { name: "Daftar", price: 8000, qty: 5 }] },
    { promo: "MINUS20K", items: [{ name: "Quloqchin", price: 150000, qty: 1 }] },
    { promo: null, items: [] },
    { promo: null, items: [{ name: "Ruchka", price: 3000, qty: 0 }] },
];

for (const cart of carts) {
    const r = checkout(cart);
    console.log(r.ok ? `${r.value.subtotal} - ${r.value.discount} + ${r.value.tax} = ${r.value.total}` : `Xato: ${r.error}`);
}
console.log(carts[0].total); // asl savatcha o'zgarmadi
